"""Customer data persistence repository."""

from typing import Dict, Optional
from models import CustomerProfile


class CustomerRepository:
    def __init__(self):
        self._storage: Dict[str, dict] = {}

    def save(self, profile: CustomerProfile) -> None:
        # BUG: Persists with dictionary key "timestamp" instead of model attribute "created_at_ts"
        self._storage[profile.customer_id] = {
            "customer_id": profile.customer_id,
            "name": profile.name,
            "email": profile.email,
            "tier": profile.tier,
            "timestamp": profile.created_at_ts,
        }

    def find_by_id(self, customer_id: str) -> Optional[CustomerProfile]:
        data = self._storage.get(customer_id)
        if not data:
            return None
        # BUG: Expects "created_at_ts" but saved as "timestamp", resulting in KeyError or 0
        ts = data.get("created_at_ts", 0)
        return CustomerProfile(
            customer_id=data["customer_id"],
            name=data["name"],
            email=data["email"],
            tier=data["tier"],
            created_at_ts=ts,
        )

repo_files.serializer.py:
"""API serialization and wire transformation."""

from typing import Any, Dict
from models import CustomerProfile


class CustomerSerializer:
    @staticmethod
    def to_wire(profile: CustomerProfile) -> Dict[str, Any]:
        # BUG: Wire schema contract specifies "created_at_ts" integer and uppercase tier,
        # but serializer outputs "created_at" string
        return {
            "id": profile.customer_id,
            "full_name": profile.name,
            "email_address": profile.email,
            "account_tier": profile.tier.upper(),
            "created_at": str(profile.created_at_ts),
        }

repo_files.service.py:
"""Customer domain management service."""

from typing import Any, Dict, Optional
from models import CustomerProfile
from repository import CustomerRepository
from serializer import CustomerSerializer


class CustomerService:
    def __init__(self, repo: CustomerRepository):
        self.repo = repo

    def register_customer(self, customer_id: str, name: str, email: str, tier: str, ts: int) -> CustomerProfile:
        profile = CustomerProfile(customer_id, name, email, tier, ts)
        self.repo.save(profile)
        return profile

    def get_wire_payload(self, customer_id: str) -> Optional[Dict[str, Any]]:
        profile = self.repo.find_by_id(customer_id)
        if not profile:
            return None
        return CustomerSerializer.to_wire(profile)

